def test_frozen_slots(num_attrs):
    attrs = [f'a{i}' for i in range(num_attrs)]
    C = attr.make_class('C', attrs, slots=True, frozen=True)
    def create():
        return C(*[i for i in range(num_attrs)])

    t = timeit.Timer(create)
    print(f"{num_attrs} attrs: {t.timeit(number=100000) / 100000 * 1e6:.2f} us")

if __name__ == "__main__":
    for n in [1, 10, 100]:
        test_frozen_slots(n)

